import pandas as pd
import numpy as np

# Define the indicators
def calculate_CCI(data, period):
    tp = (data['high'] + data['low'] + data['close']) / 3
    cci = pd.Series((tp - tp.rolling(window=period).mean()) / (0.015 * tp.rolling(window=period).std()), name='CCI')
    return cci

def calculate_ATR(data, period):
    high_low = data['high'] - data['low']
    high_close = (data['high'] - data['close'].shift(1)).abs()
    low_close = (data['low'] - data['close'].shift(1)).abs()
    ranges = pd.concat([high_low, high_close, low_close], axis=1)
    true_range = ranges.max(axis=1)
    atr = true_range.rolling(window=period).mean()
    return atr

# Define the strategy
class MeanReversionStrategy:
    def __init__(self, data):
        self.data = data
        self.cci = calculate_CCI(data, 20)
        self.atr = calculate_ATR(data, 14)

    def generate_signals(self):
        signals = pd.DataFrame(index=self.data.index)
        signals['long'] = np.where(self.cci < -100, 1, 0)
        signals['short'] = np.where(self.cci > 100, -1, 0)
        return signals

    def calculate_position_size(self, equity):
        return 0.02 * equity

    def calculate_stop_loss(self, position_size, entry_price):
        return entry_price * 0.95

    def calculate_take_profit(self, position_size, entry_price):
        return entry_price * 1.1

# Define the risk management
class KellyCriterion:
    def __init__(self, p, q, b):
        self.p = p
        self.q = q
        self.b = b

    def calculate_optimal_f(self, win_rate, loss_rate):
        return (self.p * self.b - self.q) / (self.b ** 2)

# Backtest the strategy
def backtest_strategy(data, initial_equity):
    strategy = MeanReversionStrategy(data)
    signals = strategy.generate_signals()
    equity = initial_equity
    positions = []
    for i in range(len(data)):
        if signals['long'].iloc[i] == 1:
            position_size = strategy.calculate_position_size(equity)
            entry_price = data['close'].iloc[i]
            stop_loss = strategy.calculate_stop_loss(position_size, entry_price)
            take_profit = strategy.calculate_take_profit(position_size, entry_price)
            positions.append({'position_size': position_size, 'entry_price': entry_price, 'stop_loss': stop_loss, 'take_profit': take_profit})
        elif signals['short'].iloc[i] == -1:
            position_size = strategy.calculate_position_size(equity)
            entry_price = data['close'].iloc[i]
            stop_loss = strategy.calculate_stop_loss(position_size, entry_price)
            take_profit = strategy.calculate_take_profit(position_size, entry_price)
            positions.append({'position_size': position_size, 'entry_price': entry_price, 'stop_loss': stop_loss, 'take_profit': take_profit})
        for position in positions:
            if data['close'].iloc[i] >= position['take_profit']:
                equity += position['position_size'] * (position['take_profit'] - position['entry_price'])
                positions.remove(position)
            elif data['close'].iloc[i] <= position['stop_loss']:
                equity -= position['position_size'] * (position['entry_price'] - position['stop_loss'])
                positions.remove(position)
    return equity

# Test the strategy
data = pd.read_csv('data.csv')
